import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';
const artifact=path.resolve('artifacts/platform/wpforms-aliases'),temp=await mkdtemp(path.join(tmpdir(),'wpf-alias-authoring-'));let browser,server;const cases=[];
try{await cp(path.join(artifact,'project'),temp,{recursive:true});const config=JSON.parse(await readFile(path.join(temp,'forms.json'))),form=config.forms.find(f=>f.route==='/formatted-request/'&&f.provider==='wpforms');assert.ok(form);assert.equal(form.fields.filter(f=>f.inputMask).length,4);form.delivery={endpoint:'/local-proof',format:'json'};form.fields[0].inputMask.inputFormat='dd/mm/yyyy';await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:844}});let posts=0,payload;await page.route('**/local-proof',r=>{posts++;payload=r.request().postDataJSON();return r.fulfill({contentType:'application/json',body:'{"ok":true}'});});await page.goto(server.url+'/formatted-request/',{waitUntil:'networkidle'});const inputs=page.locator('[data-cloner-input-mask]');assert.equal(await inputs.count(),4);for(const [i,value]of ['29022024','owner@example.test','25','12.75'].entries())await inputs.nth(i).pressSequentially(value);assert.equal(await inputs.nth(0).inputValue(),'29/02/2024');await page.locator('form.wpforms-form button[type=submit]').click();await page.waitForFunction(()=>document.querySelector('form.wpforms-form [role=status]').textContent.includes('accepted'));assert.equal(posts,1);assert.equal(payload[form.fields[0].name],'29/02/2024');assert.equal(payload[form.fields[1].name],'owner@example.test');assert.equal(payload[form.fields[2].name],'25');assert.equal(payload[form.fields[3].name],'12.75');assert.ok(!Object.keys(payload).some(k=>/token|nonce/.test(k)));cases.push({width,authoredDateFormat:true,configuredDelivery:true,interceptedPosts:posts});await page.close();}
await writeFile(path.join(artifact,'alias-authoring-check.json'),JSON.stringify({generatedScripts:true,cases,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length}));}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
